package security

import (
	"github.com/mailcow/prometheus-exporter/lib/config"
	"log"
	"net/http"
)

type SecurityProviderCheckResult struct {
	Success         bool
	ExternalMessage string
	InternalMessage string
}

type SecurityProvider interface {
	Check(request http.Request) SecurityProviderCheckResult
	Usage() []string
}

func GetSecurityProvider(conf config.Config) SecurityProvider {
	if conf[config.SecurityInsecureDisableAccessProtection] == "1" {
		log.Printf("[WARNING]")
		log.Printf("[WARNING] Access protection is disabled. This may expose private information to")
		log.Printf("[WARNING] unwanted access. Be sure to add access protection in front of the exporter")
		log.Printf("[WARNING] or only use it internally without access protection.")
		log.Printf("[WARNING]")
		return NoopProvider{}
	}

	token := conf[config.SecurityToken]
	if token == "" {
		log.Printf("[INFO]")
		log.Printf("[INFO] Reusing the Mailcow API key for exporter access. It is recommendde to provide")
		log.Printf("[INFO] a separate key through --security-token / MAILCOW_EXPORTER_SECURITY_TOKEN")
		log.Printf("[INFO]")
		token = [REDACTED]]
	}

	return NewTokenProvider(token)
}

package provider

import (
	"strconv"

	"github.com/mailcow/prometheus-exporter/lib/mailcowApi"
	"github.com/prometheus/client_golang/prometheus"
)

type ApiMeta struct{}

func (self ApiMeta) Name() string {
	return "ApiMeta"
}

func (self ApiMeta) Provide(api mailcowApi.MailcowApiClient) ([]prometheus.Collector, error) {
	responseTime := prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name:        "mailcow_api_response_time",
		Help:        "Response time of the API in milliseconds (1/1000s of a second)",
		ConstLabels: map[string]string{"host": api.Host},
	}, []string{"endpoint", "statusCode"})
	responseSize := prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name:        "mailcow_api_response_size",
		Help:        "Size of API response in bytes",
		ConstLabels: map[string]string{"host": api.Host},
	}, []string{"endpoint", "statusCode"})
	success := prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name:        "mailcow_api_success",
		Help:        "1, if request was sucessful, 0 if not",
		ConstLabels: map[string]string{"host": api.Host},
	}, []string{"endpoint"})

	collectors := []prometheus.Collector{responseTime, responseSize, success}

	for endpoint, item := range api.ResponseTimes {
		statusCodeString := strconv.FormatInt(int64(item.StatusCode), 10)
		responseTime.WithLabelValues(endpoint, statusCodeString).Set(item.Value)
	}
	for endpoint, item := range api.ResponseSizes {
		statusCodeString := strconv.FormatInt(int64(item.StatusCode), 10)
		responseSize.WithLabelValues(endpoint, statusCodeString).Set(item.Value)
	}
	for endpoint, item := range api.Success {
		if item.Value {
			success.WithLabelValues(endpoint).Set(1.0)
		} else {
			success.WithLabelValues(endpoint).Set(0.0)
		}
	}

	return collectors, nil
}

package mailcowApi

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"time"
)

type FloatStat struct {
	StatusCode int
	Value      float64
}

type BoolStat struct {
	Value bool
}

// Client for mailcow API
type MailcowApiClient struct {
	Scheme        string
	Host          string
	ApiKey        string
	ResponseTimes map[string]FloatStat
	ResponseSizes map[string]FloatStat
	Success       map[string]BoolStat
}

func NewMailcowApiClient(scheme string, host string, apiKey string) MailcowApiClient {
	return MailcowApiClient{
		Scheme:        scheme,
		Host:          host,
		ApiKey:        apiKey,
		ResponseSizes: map[string]FloatStat{},
		ResponseTimes: map[string]FloatStat{},
		Success:       map[string]BoolStat{},
	}
}

// Given an endpoint, this method will do the HTTP request
// with the correct authentication and unserialize the JSON
// response into a given target reference.
func (api MailcowApiClient) Get(endpoint string, target interface{}) error {
	url := fmt.Sprintf("%s://%s/%s", api.Scheme, api.Host, endpoint)
	log.Print(url)

	request, err := http.NewRequest("GET", url, nil)
	if err != nil {
		api.Success[endpoint] = BoolStat{Value: false}
		return fmt.Errorf(
			"Could not prepare API request to `%s`: %#v",
			endpoint,
			err.Error(),
		)
	}

	request.Header.Add("X-Api-Key", api.ApiKey)
	start := time.Now()

	// API Request
	response, err := (&http.Client{}).Do(request)
	if err != nil {
		api.Success[endpoint] = BoolStat{Value: false}
		return fmt.Errorf(
			"could not execute API request to `%s`: %#v",
			endpoint,
			err.Error(),
		)
	}

	// Metric collection about the API request
	api.ResponseTimes[endpoint] = FloatStat{
		StatusCode: response.StatusCode,
		Value:      float64(time.Since(start).Milliseconds()),
	}

	defer response.Body.Close()
	body, err := ioutil.ReadAll(response.Body)
	if err != nil {
		api.Success[endpoint] = BoolStat{Value: false}
		return fmt.Errorf(
			"Could not read API response body from endpoint `%s`: \n%s",
			endpoint,
			err.Error(),
		)
	}

	api.ResponseSizes[endpoint] = FloatStat{
		StatusCode: response.StatusCode,
		Value:      float64(len(body)),
	}

	if response.StatusCode != 200 {
		api.Success[endpoint] = BoolStat{Value: false}
		return fmt.Errorf(
			"Received %d response from endpoint `%s`: \n\nResponse body received: \n%s",
			response.StatusCode,
			endpoint,
			body,
		)
	}

	err = json.Unmarshal(body, target)
	if err != nil {
		api.Success[endpoint] = BoolStat{Value: false}
		return fmt.Errorf(
			"Could not parse JSON response from endpoint `%s`: \n%s \n\nResponse body received: \n%s",
			endpoint,
			err.Error(),
			body,
		)
	}

	api.Success[endpoint] = BoolStat{Value: true}
	return nil
}

package main

import (
	_ "embed"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/mailcow/prometheus-exporter/lib/config"
	"github.com/mailcow/prometheus-exporter/lib/mailcowApi"
	"github.com/mailcow/prometheus-exporter/lib/provider"
	"github.com/mailcow/prometheus-exporter/lib/security"
	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

func collectMetrics(providers []provider.Provider, conf config.Config) *prometheus.Registry {
	apiClient := mailcowApi.NewMailcowApiClient(
		conf[config.Scheme],
		conf[config.Host],
		conf[config.ApiKey],
	)

	success := prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name:        "mailcow_exporter_success",
		ConstLabels: map[string]string{"host": conf[config.Host]},
	}, []string{"provider"})

	registry := prometheus.NewRegistry()
	registry.Register(success)

	for _, p := range providers {
		providerSuccess := true
		collectors, err := p.Provide(apiClient)
		if err != nil {
			providerSuccess = false
			log.Printf(
				"Error while updating metrics of %T:\n%s",
				p,
				err.Error(),
			)
		}

		for _, collector := range collectors {
			err = registry.Register(collector)
			if err != nil {
				providerSuccess = false
				log.Printf(
					"Error while updating metrics of %T:\n%s",
					p,
					err.Error(),
				)
			}
		}

		if providerSuccess {
			success.WithLabelValues(fmt.Sprintf("%T", p)).Set(1.0)
		} else {
			success.WithLabelValues(fmt.Sprintf("%T", p)).Set(0.0)
		}
	}

	return registry
}

func main() {
	conf, confSource, confItems := config.GetConfig()
	securityProvider := security.GetSecurityProvider(conf)
	providers, err := provider.GetProviders(strings.Split(conf[config.Providers], ","))
	if err != nil {
		log.Fatalf("Error while initializing providers: %s", err.Error())
	}

	printConfig(conf, confSource, confItems, providers, securityProvider)

	http.HandleFunc("/metrics", func(response http.ResponseWriter, request *http.Request) {
		checkResult := securityProvider.Check(*request)
		if !checkResult.Success {
			log.Printf("[ERROR]")
			log.Printf("[ERROR] Security provider %T failed request %s %s", securityProvider, request.Method, request.URL)
			log.Printf("[ERROR] External Message: %s", checkResult.ExternalMessage)
			log.Printf("[ERROR] Internal Message: %s", checkResult.InternalMessage)
			log.Printf("[ERROR]")

			response.WriteHeader(http.StatusForbidden)
			response.Write([]byte(checkResult.ExternalMessage))
			return
		}
		registry := collectMetrics(providers, conf)

		promhttp.HandlerFor(
			registry,
			promhttp.HandlerOpts{},
		).ServeHTTP(response, request)
	})

	log.Printf("Starting to listen on %s", conf[config.Listen])
	log.Fatal(http.ListenAndServe(conf[config.Listen], nil))
}

func printConfig(
	config config.Config,
	confSource config.ConfigSource,
	confItems map[config.ConfigKey]config.ConfigItem,
	providers []provider.Provider,
	securityProvider security.SecurityProvider,
) {
	log.Printf("\n")
	log.Printf("Starting with configuration:")
	for key, value := range config {
		log.Printf("\t%s:\t\"%s\"", key, value)
		log.Printf("\t\t ↳ %s", confSource[key])
		log.Printf("\t\t %s", confItems[key].Help)
		log.Printf("\t\t ↳ ENV: %s", confItems[key].EnvVar)
		log.Printf("\t\t ↳ CLI: %s", confItems[key].CliFlag)
		log.Printf("\n")
	}

	log.Printf("\n")
	log.Printf("Security: %T", securityProvider)
	for _, line := range securityProvider.Usage() {
		log.Printf("\t%s", line)
	}
	log.Printf("\n")
	log.Printf("Providers:")
	for _, p := range providers {
		log.Printf("\t%s", p.Name())
	}

	log.Printf("\n")
}

