import (
	"github.com/mailcow/prometheus-exporter/lib/mailcowApi"
	"github.com/prometheus/client_golang/prometheus"
)

// Mailq provider.
// This provider uses the `/api/v1/get/mailq/all` endpoint
// in order to gather metrics.
type Mailq struct{}

type queueResponseItem struct {
	QueueName string `json:"queue_name"`
	Sender    string
}

func (Mailq) Name() string {
	return "Mailq"
}

func (mailq Mailq) Provide(api mailcowApi.MailcowApiClient) ([]prometheus.Collector, error) {
	gauge := *prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name:        "mailcow_mailq",
		Help:        "Length of the queue",
		ConstLabels: map[string]string{"host": api.Host},
	}, []string{"queue", "sender"})

	body := make([]queueResponseItem, 0)
	err := api.Get("api/v1/get/mailq/all", &body)
	if err != nil {
		return []prometheus.Collector{gauge}, err
	}

	for _, item := range body {
		gauge.WithLabelValues(item.QueueName, item.Sender).Inc()
	}

	return []prometheus.Collector{gauge}, nil
}

package config

import (
	"flag"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/mailcow/prometheus-exporter/lib/provider"
)

type ConfigKey string

const (
	Scheme                                  ConfigKey = "scheme"
	Host                                    ConfigKey = "host"
	ApiKey                                  ConfigKey = "apiKey"
	Listen                                  ConfigKey = "listen"
	SecurityToken                           ConfigKey = "securityToken"
	SecurityInsecureDisableAccessProtection ConfigKey = "securityInsecureDisableAccessProtection"
	Providers                               ConfigKey = "providers"
)

type Config map[ConfigKey]string
type ConfigSource map[ConfigKey]string
type ConfigItem struct {
	EnvVar   string
	Help     string
	CliFlag  string
	Default  string
	Required bool
}

var (
	configItems = map[ConfigKey]ConfigItem{
		Scheme: ConfigItem{
			EnvVar:  "MAILCOW_EXPORTER_SCHEME",
			CliFlag: "scheme",
			Default: "https",
			Help:    "The Scheme used to access the mailcow API (http/https)",
		},
		Host: ConfigItem{
			EnvVar:   "MAILCOW_EXPORTER_HOST",
			CliFlag:  "host",
			Required: true,
			Help:     "The hostname of the mailcow instance",
		},
		ApiKey: ConfigItem{
			EnvVar:   "MAILCOW_EXPORTER_API_KEY",
			CliFlag:  "api-key",
			Required: true,
			Help:     "The API Key used to access mailcow",
		},
		Listen: ConfigItem{
			EnvVar:  "MAILCOW_EXPORTER_LISTEN",
			CliFlag: "listen",
			Default: ":9099",
			Help:    "Hostname and port the exporter listens on",
		},
		SecurityToken: ConfigItem{
			EnvVar:  "MAILCOW_EXPORTER_SECURITY_TOKEN",
			CliFlag: "security-token",
			Help:    "The token that must be provided through the ?token=... URL parameter when accessing the exporter.\nThis defaults to the mailcow API Token if nothing is provided.",
		},
		SecurityInsecureDisableAccessProtection: ConfigItem{
			EnvVar:  "MAILCOW_EXPORTER_SECURITY_DISABLE_ACCESS_PROTECTION",
			CliFlag: "security-insecure-disable-access-protection",
			Default: "0",
			Help:    "Disables access protection for the exporter if set to 1.\nThis may expose sensitive information if no other security precautions are used",
		},
		Providers: {
			EnvVar:  "MAILCOW_EXPORTER_ACTIVE_PROVIDERS",
			CliFlag: "providers",
			Default: strings.Join(provider.ProviderNames(), ","),
			Help:    "Comma separated list of active providers. By default, all providers are active",
		},
	}
)

func GetConfig() (Config, ConfigSource, map[ConfigKey]ConfigItem) {
	// Gather flags
	flagValues := map[ConfigKey]*string{}
	for key, configItem := range configItems {
		flagValues[key] = flag.String(
			configItem.CliFlag,
			"",
			buildHelpString(configItem),
		)
	}

	// Parse Flags
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
		fmt.Fprintf(os.Stderr, "Precedence of config vars: CLI flag overrides environment variable overrides default value")
		fmt.Fprintf(os.Stderr, "\n\n")
		flag.PrintDefaults()
	}
	flag.Parse()

	config := Config{}
	configSource := ConfigSource{}
	// Apply default values to config
	for key, configItem := range configItems {
		config[key] = configItem.Default
		configSource[key] = "default value"
	}

	// Apply environment variables to config
	for key, configItem := range configItems {
		env := os.Getenv(configItem.EnvVar)
		if env != "" {
			config[key] = env
			configSource[key] = fmt.Sprintf("env %s", configItem.EnvVar)
		}
	}

	// Apply flags to config
	for key, _ := range configItems {
		if *flagValues[key] != "" {
			config[key] = *flagValues[key]
			configSource[key] = fmt.Sprintf("CLI: --%s=%s", key, *flagValues[key])
		}
	}

	validationErrors := []string{}
	for key, configItem := range configItems {
		if configItem.Required && config[key] == "" {
			validationErrors = append(validationErrors, buildValidationError(key, configItem))
		}
	}
	if len(validationErrors) > 0 {
		log.Fatalf("Configuration validation errors:\n\t%s", strings.Join(validationErrors, "\n\t"))
	}

	return config, configSource, configItems
}

func buildHelpString(item ConfigItem) string {
	additions := []string{}

	if item.Default != "" {
		additions = append(additions, fmt.Sprintf("default:  \"%s\"", item.Default))
	}
	if item.EnvVar != "" {
		env := os.Getenv(item.EnvVar)
		additions = append(additions, fmt.Sprintf("env:      %s=\"%s\"", item.EnvVar, env))
	}
	additions = append(additions, fmt.Sprintf("CLI:      --%s", item.CliFlag))
	if item.Required {
		additions = append(additions, "[required]")
	}

	help := item.Help
	for _, addition := range additions {
		help += fmt.Sprintf("\n\t%s", addition)
	}

	return help
}

func buildValidationError(key ConfigKey, item ConfigItem) string {
	methods := []string{}
	if item.EnvVar != "" {
		methods = append(methods, fmt.Sprintf("env: %s", item.EnvVar))
	}
	if item.CliFlag != "" {
		methods = append(methods, fmt.Sprintf("cli: --%s", item.CliFlag))
	}

	return fmt.Sprintf("%s: required. Provide it with one of the following methods: %s", key, strings.Join(methods, ", "))
}

package provider

import (
	"encoding/json"

	"github.com/mailcow/prometheus-exporter/lib/mailcowApi"

	"github.com/prometheus/client_golang/prometheus"
)

// Mailbox Provider. This provider uses the `/api/v1/get/mailbox/all`
// endpoint in order to gather metrics.
type Mailbox struct{}

type mailboxItem struct {
	Username      string      `json:"username"`
	LastImapLogin json.Number `json:"last_imap_login"`
	Quota         json.Number `json:"quota"`
	QuotaUsed     json.Number `json:"quota_used"`
	Messages      json.Number `json:"messages"`
}

func (Mailbox) Name() string {
	return "Mailbox"
}

// All mailbox gauges have the same options anyways.
func mailboxGauge(name string, description string, host string) prometheus.GaugeVec {
	return *prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name:        name,
		Help:        description,
		ConstLabels: map[string]string{"host": host},
	}, []string{"mailbox"})
}

func (mailbox Mailbox) Provide(api mailcowApi.MailcowApiClient) ([]prometheus.Collector, error) {
	lastLogin := mailboxGauge("mailcow_mailbox_last_login", "Timestamp of the last IMAP login for this mailbox", api.Host)
	quotaAllowed := mailboxGauge("mailcow_mailbox_quota_allowed", "Quota maximum for the mailbox in bytes", api.Host)
	quotaUsed := mailboxGauge("mailcow_mailbox_quota_used", "Current syze of the mailbox in bytes", api.Host)
	messages := mailboxGauge("mailcow_mailbox_messages", "Number of messages in the mailbox", api.Host)
	collectors := []prometheus.Collector{lastLogin, quotaAllowed, quotaUsed, messages}

	body := make([]mailboxItem, 0)
	err := api.Get("api/v1/get/mailbox/reduced", &body)
	if err != nil {
		return collectors, err
	}

	for _, m := range body {
		valueLastImapLogin, err := m.LastImapLogin.Float64()
		if err != nil {
			return collectors, err
		}

		valueQuota, err := m.Quota.Float64()
		if err != nil {
			return collectors, err
		}

		valueQuotaUsed, err := m.QuotaUsed.Float64()
		if err != nil {
			return collectors, err
		}

		valueMessages, err := m.Messages.Float64()
		if err != nil {
			return collectors, err
		}

		lastLogin.WithLabelValues(m.Username).Set(valueLastImapLogin)
		quotaAllowed.WithLabelValues(m.Username).Set(valueQuota)
		quotaUsed.WithLabelValues(m.Username).Set(valueQuotaUsed)
		messages.WithLabelValues(m.Username).Set(valueMessages)
	}

	return collectors, nil
}

package provider

import (
	"time"

	"github.com/mailcow/prometheus-exporter/lib/mailcowApi"

	"github.com/prometheus/client_golang/prometheus"
)

// Quarantine Provider. Use `NewQuarantine` to initialize this struct.
// This provider uses the `/api/v1/get/quarantine/all` endpoint
// in order to gather metrics about quarantined mails.
type Quarantine struct{}

type quarantineItem struct {
	VirusFlag int     `json:"virus_flag"`
	Score     float64 `json:"score"`
	Recipient string  `json:"rcpt"`
	Created   int64   `json:"created"`
}

func (Quarantine) Name() string {
	return "Quarantine"
}

func (quarantine Quarantine) Provide(api mailcowApi.MailcowApiClient) ([]prometheus.Collector, error) {
	countGauge := *prometheus.NewGaugeVec(prometheus.GaugeOpts{
		Name:        "mailcow_quarantine_count",
		Help:        "Number of mails currently in quarantine",
		ConstLabels: map[string]string{"host": api.Host},
	}, []string{"recipient", "is_virus"})
	scoreHist := *prometheus.NewHistogramVec(prometheus.HistogramOpts{
		Name:        "mailcow_quarantine_score",
		Help:        "Score of quarantined mails according to rspamd",
		Buckets:     []float64{0, 10, 20, 40, 60, 80, 100},
		ConstLabels: map[string]string{"host": api.Host},
	}, []string{"recipient"})
	ageHist := *prometheus.NewHistogramVec(prometheus.HistogramOpts{
		Name: "mailcow_quarantine_age",
		Help: "Age of quarantined items in seconds",
		Buckets: []float64{
			(60 * 60 * 3),       // 3 hours
			(60 * 60 * 12),      // 12 hours
			(60 * 60 * 24),      // 1 day
			(3 * 60 * 60 * 24),  // 3 days
			(7 * 60 * 60 * 24),  // 7 days
			(14 * 60 * 60 * 24), // 14 days
			(30 * 60 * 60 * 24), // 30 days
		},
		ConstLabels: map[string]string{"host": api.Host},
	}, []string{"recipient"})

	collectors := []prometheus.Collector{
		countGauge,
		scoreHist,
		ageHist,
	}

	body := make([]quarantineItem, 0)
	err := api.Get("api/v1/get/quarantine/all", &body)
	if err != nil {
		return collectors, err
	}

	virus := make(map[string]int)
	notVirus := make(map[string]int)
	for _, q := range body {
		if _, ok := virus[q.Recipient]; !ok {
			virus[q.Recipient] = 0
		}
		if _, ok := notVirus[q.Recipient]; !ok {
			notVirus[q.Recipient] = 0
		}

		if q.VirusFlag == 1 {
			virus[q.Recipient]++
		} else {
			notVirus[q.Recipient]++
		}

		age := time.Now().Unix() - q.Created
		ageHist.WithLabelValues(q.Recipient).Observe(float64(age))
		scoreHist.WithLabelValues(q.Recipient).Observe(float64(q.Score))
	}

	for recipient, count := range virus {
		countGauge.WithLabelValues(recipient, "1").Set(float64(count))
	}
	for recipient, count := range notVirus {
		countGauge.WithLabelValues(recipient, "0").Set(float64(count))
	}

	return collectors, nil
}

